; ----------------------------------------------------------------
; Keyboard check & pause toggle handler
; Checks for Ctrl-T to toggle pause flag at $50
; Falls through to joystick check or keyboard dispatch
; ----------------------------------------------------------------

KBDCHECK:
        LDA KEYBOARD                ; $C000
        CMP #$94                    ; Ctrl-T
        BEQ KBDGOT
        LDA PAUSEFLAG               ; $50
        BEQ KBDNOPAUSE
        BNE KBDCONT
KBDGOT:
        STA KBDSTRB                 ; $C010
        LDA PAUSEFLAG               ; $50
        EOR #$FF
        STA PAUSEFLAG               ; $50
        BNE KBDCONT
KBDNOPAUSE:
        JSR CHKJOY                  ; $711D
        JMP REDRAWCHECK             ; $7300

KBDCONT:
        LDA KEYBOARD                ; $C000
        JMP KBDDISPATCH             ; $7342


        .BYTE $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00 ; |##############..............##############..............##############..............##############..............|
