; ----------------------------------------------------------------
; Sprite initialization, page flip, and delay routines
; ----------------------------------------------------------------

; SPRITEINIT - Initialize sprite engine address tables
; Patches address table pointers for double-buffered rendering
SPRITEINIT:
        STA $8F32                   ; patch high byte address
        JSR HGRDATA1                ; initialize HGR data tables
        LDA #$20                    ; page 1 base ($2000)
        STA $8F1B                   ; set page 1 pointer
        LDA #$60                    ; page 2 offset
        STA $8F32                   ; set page 2 pointer
        RTS                         ; return


; ----------------------------------------------------------------
; PAGESWITCH - Toggle between HGR pages for double buffering
; PAGEFLIP: $00 = page 1 ($2000), $60 = page 2 ($4000)
; XOR with $60 flips between the two pages
; ----------------------------------------------------------------
PAGESWITCH:
        LDA PAGEFLIP                ; get current page ($00 or $60)
        EOR #$60                    ; flip: $00↔$60
        STA PAGEFLIP                ; store new draw page
        LDA $63                     ; secondary page flag
        EOR #$01                    ; toggle 0/1
        STA $63                     ; store flag
        RTS                         ; return


; ----------------------------------------------------------------
; SELECTPAGE - Switch hardware display to current page
; Reads PAGEFLIP and sets appropriate soft switch
; ----------------------------------------------------------------
SELECTPAGE:
        LDA PAGEFLIP                ; get current page
        BNE SELPAGE2                ; non-zero = page 2
        LDA LOWSCR                  ; display page 1 ($2000)
        RTS                         ; return

SELPAGE2:
        LDA HISCR                   ; display page 2 ($4000)
        RTS                         ; return


; ----------------------------------------------------------------
; Timing delays using Monitor WAIT routine
; DELAY1 - Short delay (2 iterations × $14 cycles)
; DELAY2 - Longer delay (3 iterations × $41 cycles)
; ----------------------------------------------------------------
DELAY1:
        LDY #$02                    ; 2 outer iterations
DELAY1LP:
        LDA #$14                    ; delay value = 20
        JSR WAIT                    ; ROM delay routine
        DEY                         ; next iteration
        BNE DELAY1LP                ; loop until done
        RTS                         ; return

DELAY2:
        LDY #$03                    ; 3 outer iterations
DELAY2LP:
        LDA #$41                    ; delay value = 65
        JSR WAIT                    ; ROM delay routine
        DEY                         ; next iteration
        BNE DELAY2LP                ; loop until done
        RTS                         ; return

; DELAY3 - Variable delay based on memory location
DELAY3:
        LDY $8F8D                   ; get delay count from table
L_6F84:
        LDA #$19                    ; delay value = 25
        JSR WAIT                    ; ROM delay routine
        DEY                         ; next iteration
        BNE L_6F84                  ; loop until done
        RTS                         ; return

        ; Unused/padding bytes
        ORA (SHAPE,X)               ; (data, not code)
        ORA $49                     ; (data, not code)
        .BYTE $FF                                  ; |#######|
        CLC                         ; (data/padding)
        ADC #$01                    ; (data/padding)
        RTS                         ; (data/padding)


; ----------------------------------------------------------------
; Low-level sprite column plot with shift/mask
; Uses XOR drawing for sprite toggle on/off
; Handles sub-pixel alignment via bit shifting
; ----------------------------------------------------------------
SPRITEDRAW:
        LDX #$00                    ; start at row 0
        LDY SCANLINE                ; get current scan line
        ; Calculate HGR row address
        LDA $8D52,Y                 ; row address low byte table
        STA SCRLO                   ; set screen pointer low
        LDA $8E12,Y                 ; row address high byte table
        EOR PAGEFLIP                ; apply page offset ($00/$60)
        STA SCRHI                   ; set screen pointer high
        ; Get horizontal shift/position
        LDY $57                     ; get X byte position
        LDA $8AD0,Y                 ; get shift mask from table
        STA $5C                     ; save shift count
        LDA $8BE8,Y                 ; get byte offset from table
        TAY                         ; Y = byte offset in row
        ; Get sprite pixel data
        LDA $9D1F,X                 ; get sprite byte
        AND #$80                    ; extract color bit (bit 7)
        STA $6B                     ; save color flag
        LDA $9D1F,X                 ; get sprite byte again
        AND #$7F                    ; mask off color bit
        STA $64                     ; save pixel data
        LDA #$00                    ; clear overflow byte
        STA $68                     ; for shifted bits
        ; Check if shift needed
        LDA $5C                     ; get shift count
        CMP #$01                    ; no shift needed?
        BEQ L_6FDE                  ; yes, skip shifting
        ; Shift pixels right for sub-pixel alignment
L_6FC9:
        LSR $64                     ; shift main byte right
        ROR $68                     ; catch overflow bits
        ASL $5C                     ; decrease shift counter
        BIT $5C                     ; check if done
        BPL L_6FC9                  ; continue shifting
        LSR $68                     ; final overflow adjust
        ; XOR-plot first byte (overflow pixels)
        LDA $68                     ; get overflow pixels
        ORA $6B                     ; combine with color bit
        EOR (SCRLO),Y               ; XOR with screen
        STA (SCRLO),Y               ; write back
        INY                         ; move to next byte
L_6FDE:
        ; XOR-plot main byte
        LDA $64                     ; get main pixels
        ORA $6B                     ; combine with color bit
        EOR (SCRLO),Y               ; XOR with screen
        STA (SCRLO),Y               ; write back
        INC SCANLINE                ; move to next row
        INX                         ; next sprite row
        CPX #$04                    ; done 4 rows?
        BCS L_6FF0                  ; yes, exit
        JMP HGRDATA2                ; continue with more data

L_6FF0:
        RTS                         ; return

        ; Patch routine for address tables
        STA $8FB2                   ; patch address
        STA $8FB9                   ; patch address
        STY $8FB3                   ; patch address
        STY $8FBA                   ; patch address
        RTS                         ; return


; ----------------------------------------------------------------
; ENTRY - Binary entry point
; Called when level2.bin is loaded and executed
; Initializes variables then starts the level
; ----------------------------------------------------------------
ENTRY:
        JSR $A960                   ; initialization call
        BRK                         ; (data/padding)
        STA $20                     ; initialize zero-page
ENTRYJMP:
        JMP LEVELSTART              ; begin level 2


; ----------------------------------------------------------------
; Data tables: color lookup, enemy placement coordinates
; COLORTBL - Color/hit flags for various game states
; Direction flip masks: $01=horiz, $06=vert, $07=both
; PLACESX/PLACESY - Spawn positions for cats (8 locations)
; ----------------------------------------------------------------

COLORTBL:
        .BYTE $00, $00, $00, $00, $FF, $00, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $FF, $00 ; |............................#######.....................##############..............#####################.......|
        .BYTE $01, $06, $07                        ; |#.......##....###....|
PLACESX:
        .BYTE $14, $28, $70, $50, $28, $14, $50, $70 ; |..#.#.....#.#.....###....#.#...#.#...#.#......#.#....###|
PLACESY:
        .BYTE $50, $A0, $50, $A0, $80, $90, $80, $90, $A5 ; |....#.#.....#.....#.#.....#............#.............#..#.#..#.|

; ----------------------------------------------------------------
; Sound and plot helper routines
; CLICK   - Toggle speaker if sound enabled
; ORPLOTS - OR-plot with byte-to-pixel coordinate conversion
; PLOTS   - Direct plot with byte-to-pixel conversion
; ----------------------------------------------------------------

CLICK:
        STY $30                     ; save Y register
        .BYTE $03                                  ; |##.....|
        STA SPKR                    ; toggle speaker

; OR-plot with X coordinate conversion (byte to pixel)
ORPLOTS:
        LDA X                       ; get byte position
        PHA                         ; save it
        ASL A                       ; multiply by 4
        ASL A                       ; convert to pixel X
        STA X                       ; set pixel coordinate
        JSR ORPLOT2                 ; OR-plot to HGR page 2
        PLA                         ; restore byte position
        STA X                       ; put back
        RTS                         ; return

; Direct plot with X coordinate conversion
PLOTS:
        LDA X                       ; get byte position
        PHA                         ; save it
        ASL A                       ; multiply by 4
        ASL A                       ; convert to pixel X
        STA X                       ; set pixel coordinate
        JSR PLOT2                   ; direct plot to page 2
        PLA                         ; restore byte position
        STA X                       ; put back
        RTS                         ; return


; ----------------------------------------------------------------
; BORDER - Game screen initialization
; Clears screen, draws playfield borders with alternating colors,
; renders game title text, switches to hi-res mode
; Uses orange/blue color pattern ($2A) for borders
; ----------------------------------------------------------------

BORDER:
        JSR HOME                    ; clear text screen (ROM)
        STA LOWSCR                  ; display page 1
        STA TXTSET                  ; enable text temporarily
        JSR CLRSCRN2                ; clear HGR to black
        STA TXTSET                  ; keep text visible

        ; Start at bottom-right corner
        LDA #$BF                    ; Y = 191 (bottom row)
        STA Y                       ;
        LDA #$26                    ; X = 38 (near right edge)
        STA X                       ;
        LDA #$2A                    ; orange/blue pattern
        STA COLOR                   ;

; Draw top border (right to left)
BORDER1:
        JSR ORPLOTS                 ; plot pixel
        DEC Y                       ; move up
        JSR ORPLOTS                 ; plot double-height
        INC Y                       ; move back down
        LDA COLOR                   ; alternate colors
        EOR #$7F                    ; toggle pattern
        STA COLOR                   ; set new color
        DEC X                       ; move left
        BNE BORDER1                 ; loop until left edge

; Draw left border corner
BORDER2:
        JSR ORPLOTS                 ; plot corner pixel
        LDA #$2A                    ; reset to orange/blue
        STA COLOR                   ;

; Draw left border (bottom to top)
BORDER3:
        JSR ORPLOTS                 ; plot pixel
        DEC Y                       ; move up
        LDA Y                       ; check position
        CMP #$11                    ; reached top yet?
        BCS BORDER3                 ; no, continue up

        ; Draw bottom border (left to right)
        LDA #$2A                    ; orange/blue pattern
        STA COLOR                   ;
BORDER4:
        JSR ORPLOTS                 ; plot pixel
        INC Y                       ; move down
; Continue bottom border with alternating colors
BORDER5:
        JSR ORPLOTS                 ; plot double-height
        DEC Y                       ; move back up
        LDA COLOR                   ; alternate colors
        EOR #$7F                    ; toggle pattern
        STA COLOR                   ; set new color
        INC X                       ; move right
        LDA X                       ; check position
        CMP #$26                    ; reached right edge?
        BNE BORDER4                 ; no, continue
        JSR ORPLOTS                 ; final pixel

        ; Draw right border (top to bottom)
        LDA #$2A                    ; orange/blue pattern
        STA COLOR                   ;
L_70B1:
        JSR ORPLOTS                 ; plot pixel
        INC Y                       ; move down
        LDA Y                       ; check position
        CMP #$BF                    ; reached bottom?
        BCC L_70B1                  ; no, continue

        ; Draw title text "TIME" vertically on right edge
        ; Characters: T=20, I=9, M=13, E=5
        LDA #$00                    ; Y position for text
        STA YY                      ;
        LDA #$1B                    ; (unused store)
        STA XX                      ;
        LDA #$27                    ; X = 39 (right edge)
        STA XX                      ;
        LDA #$00                    ; Y = 0 (top)
        STA YY                      ;
        LDA #$00                    ; smallest width
        STA WIDTH                   ;
        LDA #$01                    ; single height
        STA HEIGHT                  ;
        LDA #$FF                    ; white color
        STA COLORMASK               ;

        ; Draw 'T' (character 20)
        LDA #$14                    ; 'T' = 20
        JSR CHRGEN                  ; draw character
        LDA #$08                    ; Y += 8
        STA YY                      ;

        ; Draw 'I' (character 9)
        LDA #$09                    ; 'I' = 9
        JSR CHRGEN                  ; draw character
        LDA #$10                    ; Y += 8
        STA YY                      ;

        ; Draw 'M' (character 13)
        LDA #$0D                    ; 'M' = 13
        JSR CHRGEN                  ; draw character
        LDA #$18                    ; Y += 8
        STA YY                      ;

        ; Draw 'E' (character 5)
        LDA #$05                    ; 'E' = 5
        JSR CHRGEN                  ; draw character

        ; Draw timer bar on right side
        LDA #$21                    ; starting Y for timer
        STA TIME                    ;
        LDA #$D5                    ; bright color
        STA COLOR                   ;
        LDA TIME                    ; get timer Y
        STA Y                       ;
        LDA #$27                    ; X = 39 (right edge)
        STA X                       ;
BORDERTXT:
        JSR PLOTS                   ; draw timer pixel
        INC Y                       ; next row down
        LDA Y                       ; check position
        CMP #$BF                    ; reached bottom?
        BCC BORDERTXT               ; no, continue

; Enable hi-res graphics display
BORDERDONE:
        STA TXTCLR                  ; graphics mode (not text)
        STA HIRES                   ; hi-res mode
        STA MIXCLR                  ; full screen (no text)
        RTS                         ; return


; ----------------------------------------------------------------
; CHKJOY - Joystick/paddle input handler
; Reads paddle buttons (PB0/PB1/PB2) and paddle position (PREAD)
; Maps paddle values to movement directions
; Button combo indicates joystick vs keyboard mode
; ----------------------------------------------------------------

CHKJOY:
        LDA PB0                     ; read button 0
        AND PB1                     ; combine with button 1
        AND PB2                     ; combine with button 2
        BMI NOJOY                   ; all pressed = no joystick
        LDA JOYFLG                  ; check joystick mode flag
        BMI L_713C                  ; already in joystick mode
        EOR #$FF
        ; Enable joystick mode
        STA JOYFLG                  ; set joystick flag
        JSR READPDL1                ; read paddle 1 (vertical)
        LDA #$30                    ; short delay
        JSR WAIT                    ; wait for paddle settle
        JSR READPDL0                ; read paddle 0 (horizontal)
NOJOY:
        RTS                         ; return

; Toggle joystick mode and read paddles
L_713C:
        EOR #$FF                    ; flip joystick flag
        STA JOYFLG                  ; store new mode
        JSR READPDL0                ; read paddle 0 first
        LDA #$30                    ; short delay
        JSR WAIT                    ; wait for settle
        JSR READPDL1                ; read paddle 1
        RTS                         ; return

; ----------------------------------------------------------------
; READPDL1 - Read paddle 1 (vertical axis)
; Maps value to up/down movement if outside dead zone
; Dead zone: $30-$CF (center position)
; ----------------------------------------------------------------
READPDL1:
        LDX #$01                    ; paddle 1
        JSR PREAD                   ; read paddle (ROM routine)
        TYA                         ; transfer value to A
        CMP #$30                    ; below dead zone? (up)
        BCC L_716A                  ; yes, move up
        CMP #$D0                    ; above dead zone? (down)
        BCS L_7178                  ; yes, move down
        RTS                         ; in dead zone, no movement

; ----------------------------------------------------------------
; READPDL0 - Read paddle 0 (horizontal axis)
; Maps value to left/right movement if outside dead zone
; ----------------------------------------------------------------
READPDL0:
        LDX #$00                    ; paddle 0
        JSR PREAD                   ; read paddle (ROM routine)
        TYA                         ; transfer value to A
        CMP #$30                    ; below dead zone? (left)
        BCC L_7171                  ; yes, move left
        CMP #$D0                    ; above dead zone? (right)
        BCS L_717F                  ; yes, move right
        RTS                         ; in dead zone, no movement

; Paddle indicates UP - clean up stack and jump to movement
L_716A:
        PLA                         ; pop return addresses
        PLA                         ; (skip caller's caller)
        PLA                         ;
        PLA                         ;
JOYUP:
        JMP MOVUP                   ; execute upward movement

; Paddle indicates LEFT - clean up stack and jump
L_7171:
        PLA                         ; pop return addresses
        PLA                         ;
        PLA                         ;
        PLA                         ;
JOYLEFT:
        JMP MOVLE                   ; execute leftward movement

; Paddle indicates DOWN - clean up stack and jump
L_7178:
        PLA                         ; pop return addresses
        PLA                         ;
        PLA                         ;
        PLA                         ;
JOYDOWN:
        JMP MOVDO                   ; execute downward movement

; Paddle indicates RIGHT - clean up stack and jump
L_717F:
        PLA                         ; pop return addresses
        PLA                         ;
        PLA                         ;
        PLA                         ;
JOYRIGHT:
        JMP MOVRI                   ; execute rightward movement


; ----------------------------------------------------------------
; SOUNDTICK - Timer tick with sound and time decrement
; Generates ticking sound with TIME-based pitch
; Also decrements timer bar on screen
; Returns carry set if time expired
; ----------------------------------------------------------------
SOUNDTICK:
        LDY #$32                    ; 50 iterations
L_7188:
        ; Calculate delay based on remaining time
        LDA #$C0                    ; max delay base
        SBC TIME                    ; subtract current time
        LSR A                       ; divide by 2
        TAX                         ; X = delay count
L_718E:
        DEX                         ; inner delay loop
        BNE L_718E                  ; wait
        LDA SOUND                   ; check sound enabled
        BMI L_7198                  ; bit 7 = muted, skip
        STA SPKR                    ; toggle speaker (tick)
L_7198:
        DEY                         ; decrement outer loop
        BNE L_7188                  ; continue ticking

        ; Update timer bar display (erase one pixel)
        LDA #$00                    ; black color
        STA COLOR                   ; to erase
        LDA #$27                    ; X = 39 (right edge)
        STA X                       ;
        LDA TIME                    ; current time position
        STA Y                       ; Y = time value
        JSR PLOTS                   ; erase timer pixel
        INC TIME                    ; advance time
        LDA TIME                    ; check new time
        CMP #$BF                    ; '?' key
        RTS


; ----------------------------------------------------------------
; Score and status display routines
; PUTSCORE - Display 5-digit BCD score using NUMGEN
; Score stored as 3 BCD bytes: SCOREHI1, SCOREHI, SCORELO
; Each nibble is one digit (0-9)
; ----------------------------------------------------------------
PUTSCORE:
        ; Digit 1 (ten-thousands): SCOREHI1 low nibble
        LDA SCOREHI1                ; get high score byte
        AND #$0F                    ; mask to low nibble
        STA SHAPE                   ; set digit value
        LDA #$0F                    ; X position = 15
        STA XX                      ;
        LDA #$00                    ; Y position = 0 (top)
        STA YY                      ;
        LDA #$FF                    ; white color
        STA COLORMASK               ;
        JSR NUMGEN                  ; draw first digit

        ; Digit 2 (thousands): SCOREHI high nibble
        LDA SCOREHI                 ; get middle score byte
        LSR A                       ; shift high nibble down
        LSR A                       ;
        LSR A                       ;
        LSR A                       ;
        STA SHAPE                   ; set digit value
        LDA #$11                    ; X position = 17
        STA XX                      ;
        JSR NUMGEN                  ; draw second digit

        ; Digit 3 (hundreds): SCOREHI low nibble
        LDA SCOREHI                 ; get middle score byte
        AND #$0F                    ; mask to low nibble
        STA SHAPE                   ; set digit value
        LDA #$13                    ; X position = 19
        STA XX                      ;
        JSR NUMGEN                  ; draw third digit

        ; Digit 4 (tens): SCORELO high nibble
        LDA SCORELO                 ; get low score byte
        LSR A                       ; shift high nibble down
        LSR A                       ;
        LSR A                       ;
        LSR A                       ;
        STA SHAPE                   ; set digit value
        LDA #$15                    ; X position = 21
        STA XX                      ;
        JSR NUMGEN                  ; draw fourth digit

        ; Digit 5 (ones): SCORELO low nibble
        LDA SCORELO                 ; get low score byte
        AND #$0F                    ; mask to low nibble
        STA SHAPE                   ; set digit value
        LDA #$17                    ; X position = 23
        STA XX                      ;
        JSR NUMGEN                  ; draw fifth digit
        CLC                         ; clear carry (success)
        RTS                         ; return

; ----------------------------------------------------------------
; PUTLIVES - Display "LIVES" text and remaining lives count
; Uses CHRGEN for text: L=12, I=9, V=22, E=5, S=19
; Then displays lives count as digit using NUMGEN
; ----------------------------------------------------------------
PUTLIVES:
        LDA #$00                    ; starting X position
        STA XX                      ;
        STA YY                      ; Y = 0 (top row)
        LDA #$00                    ; smallest width
        STA WIDTH                   ;
        LDA #$01                    ; single height
        STA HEIGHT                  ;
        LDA #$FF                    ; white color
        STA COLORMASK               ;

        ; Draw "LIVES" text character by character
        LDA #$0C                    ; 'L' = 12
        JSR CHRGEN                  ; draw 'L'
        INC XX                      ; advance cursor
        LDA #$09                    ; 'I' = 9
        JSR CHRGEN                  ; draw 'I'
        INC XX                      ; advance cursor
        LDA #$16                    ; 'V' = 22
        JSR CHRGEN                  ; draw 'V'
        INC XX                      ; advance cursor
        LDA #$05                    ; 'E' = 5
        JSR CHRGEN                  ; draw 'E'
        INC XX                      ; advance cursor
        LDA #$13                    ; 'S' = 19
        JSR CHRGEN                  ; draw 'S'
        INC XX                      ; advance cursor
        LDA YOULIVES                ; get lives count
        STA SHAPE                   ; set as digit to draw
PUTNUM:
        JMP NUMGEN                  ; draw digit and return

; ----------------------------------------------------------------
; PUTHITS - Display hit indicator (3 colored bars)
; Uses COLORTBL to get colors based on hit count (0-3)
; Draws 3 pairs of pixels at different Y positions
; ----------------------------------------------------------------
PUTHITS:
        LDA YOUHITS                 ; get current hit count
        ASL A                       ; multiply by 4
        ASL A                       ; (4 bytes per color set)
        TAY                         ; Y = color table index
        ; Draw first indicator bar (Y=2-3)
        LDA COLORTBL,Y              ; get first color
        STA COLOR                   ; set draw color
        LDA #$09                    ; X position
        STA X                       ;
        LDA #$02                    ; Y position
        STA Y                       ;
        STY PADCOUNT                ; save table index
        JSR PLOTS                   ; draw pixel
        INC Y                       ; next row
        JSR PLOTS                   ; draw pixel

        ; Draw second indicator bar (Y=7-8)
        LDY PADCOUNT                ; restore index
        LDA $7008,Y                 ; get second color
        STA COLOR                   ; set draw color
        LDA #$07                    ; Y position
        STA Y                       ;
        JSR PLOTS                   ; draw pixel
        INC Y                       ; next row
        JSR PLOTS                   ; draw pixel

        ; Draw third indicator bar (Y=12-13)
        LDY PADCOUNT                ; restore index
        LDA $7009,Y                 ; get third color
        STA COLOR                   ; set draw color
        LDA #$0C                    ; Y position
        STA Y                       ;
        JSR PLOTS                   ; draw pixel
        INC Y                       ; next row
        JMP PLOTS                   ; draw pixel and return


; ----------------------------------------------------------------
; PLACEFOOD - Place food item at pseudo-random position
; Uses ROM pages ($F000, $F800) as random number source
; Food sprite is shape $1C, drawn in white ($7F)
; ----------------------------------------------------------------
PLACEFOOD:
        INC COUNT                   ; increment random counter
        LDY COUNT                   ; use as ROM index
        ; Generate random X position
        LDA $F000,Y                 ; get pseudo-random byte
        CLC                         ; prepare for add
        ADC #$0C                    ; offset from left edge
        AND #$7F                    ; mask to playfield width
        STA X                       ; set food X
        ; Generate random Y position
        LDA $F800,Y                 ; get another random byte
        AND #$7F                    ; mask to playfield height
        CLC                         ; prepare for add
        ADC #$1E                    ; offset from top
        STA Y                       ; set food Y
        ; Draw food sprite
        LDA #$1C                    ; food sprite shape
        STA SHAPE                   ;
        LDA #$7F                    ; white color
        STA COLOR                   ;
        JMP DRAW2                   ; draw and return

L_72A1:
        JMP KBDJMP                  ; jump to keyboard handler


; ----------------------------------------------------------------
; UPDATEYOU - Player update (demo mode auto-movement)
; In demo mode, reads pseudo-random values from ROM for movement.
; In play mode, jumps to keyboard/joystick handler (KBDJMP).
; Saves current position in TEMPX/Y for sprite redraw.
; ----------------------------------------------------------------
UPDATEYOU:
        ; Save current position for later sprite update
        LDA YOUX                    ; get player X
        STA TEMPX                   ; save for redraw
        LDA YOUY                    ; get player Y
        STA TEMPY                   ; save for redraw
        LDA YOUSHP                  ; get player sprite
        STA TEMPSHP                 ; save for redraw
        ; Check if in demo mode
        LDA DEMO                    ; check demo flag
        BMI L_72A1                  ; if set, use keyboard instead

        ; Demo mode: pseudo-random movement
        DEC YOUC                    ; decrement demo counter
        BNE L_72C1                  ; not zero, skip reload
        INC COUNT                   ; advance random counter
        LDY COUNT                   ; get as index
        LDA $E000,Y                 ; load from ROM
        STA YOUC                    ; set new demo counter
L_72C1:
        LDA YOUC                    ; get demo counter
        AND #$1F                    ; mask to 0-31
        STA YOUC                    ; store masked value
        ; Get random direction bits
        LDY COUNT                   ; get random index
        LDA $F700,Y                 ; load direction bits
        ROR A                       ; shift for processing
        ROR A                       ;
        BMI L_72D4
        INC YOUX                    ; $81
        BNE L_72D6
; Demo mode: move left
L_72D4:
        DEC YOUX                    ; move left
L_72D6:
        ; Get vertical direction from ROM
        INY                         ; advance random index
        LDA $F000,Y                 ; get random byte
        ROR A                       ; shift bit into carry
        ROR A                       ; check sign
        BMI L_72E2                  ; negative = move up
        INC YOUY                    ; positive = move down
        BNE L_72E4                  ; (always taken)
L_72E2:
        DEC YOUY                    ; move up

; Clamp position to playfield boundaries
L_72E4:
        ; Check left boundary (X = 5)
        LDA YOUX                    ; get X position
        CMP #$05                    ; at left edge?
        BNE L_72EC                  ; no, skip
        INC YOUX                    ; push back right
L_72EC:
        ; Check right boundary (X = $91 = 145)
        CMP #$91                    ; at right edge?
        BNE L_72F2                  ; no, skip
        DEC YOUX                    ; push back left
L_72F2:
        ; Check top boundary (Y = $15 = 21)
        LDA YOUY                    ; get Y position
        CMP #$15                    ; at top edge?
        BCS L_72FA                  ; no, skip
        INC YOUY                    ; push back down
L_72FA:
        ; Check bottom boundary (Y = $AA = 170)
        CMP #$AA                    ; at bottom edge?
        BCC REDRAWCHECK             ; no, continue
        DEC YOUY                    ; push back up

; ----------------------------------------------------------------
; REDRAWCHECK - Check if player moved, redraw if needed
; Compares current position with saved TEMPX/TEMPY
; ----------------------------------------------------------------
REDRAWCHECK:
        LDA TEMPX                   ; get old X position
        CMP YOUX                    ; compare with new X
        BNE L_730D                  ; different = need redraw
        LDA TEMPY                   ; get old Y position
        CMP YOUY                    ; compare with new Y
        BNE L_730D                  ; different = need redraw
        RTS                         ; no movement, done

; Position changed - erase old sprite, draw new sprite
L_730D:
        ; Erase sprite at old position
        LDA TEMPX                   ; old X
        STA X                       ; set draw X
        LDA TEMPY                   ; old Y
        STA Y                       ; set draw Y
        LDA TEMPSHP                 ; old sprite shape
        STA SHAPE                   ; set for draw
        LDA #$00                    ; no collision flag
        STA FLAG                    ; disable collision check
        LDA #$FF                    ; white color (for XOR erase)
        STA COLOR                   ;
        JSR DRAWYOU                 ; erase old sprite

        ; Draw sprite at new position
        LDA YOUX                    ; new X
        STA X                       ; set draw X
        LDA YOUY                    ; new Y
        STA Y                       ; set draw Y
        LDA YOUSHP                  ; current sprite shape
        STA SHAPE                   ; set for draw
        LDA #$7F                    ; enable collision flag
        STA FLAG                    ; check for collisions
        LDA #$FF                    ; white color
        STA COLOR                   ;
        JSR DRAWYOU                 ; draw new sprite
        RTS                         ; return

        JMP PAUSEWAIT               ; (unreachable)

KBDJMP:
        JMP KBDCHECK                ; jump to keyboard handler


; ----------------------------------------------------------------
; KBDDISPATCH - Keyboard dispatch for player movement
; W=$D7=Up, S=$D3=Down, J=$CA=Left, K=$CB=Right
; Falls through to REDRAWCHECK if no movement key pressed
; ----------------------------------------------------------------
KBDDISPATCH:
        CMP #$D7                    ; 'W' key? (up)
        BEQ MOVUP                   ; yes, move up
        CMP #$D3                    ; 'S' key? (down)
        BEQ MOVDO                   ; yes, move down
        CMP #$CA                    ; 'J' key? (left)
        BEQ MOVLE                   ; yes, move left
        CMP #$CB                    ; 'K' key? (right)
        BEQ MOVRI                   ; yes, move right
        NOP                         ; padding (timing)
        NOP                         ;
        NOP                         ;
        JMP REDRAWCHECK             ; no valid key, check redraw

; ----------------------------------------------------------------
; Movement handlers - update position and sprite, check bounds
; ----------------------------------------------------------------
MOVUP:
        LDA YOUY                    ; get Y position
        CMP #$13                    ; at top boundary?
        BEQ REDRAWCHECK             ; yes, can't move
        DEC YOUY                    ; move up
        LDA #$00                    ; facing up sprite
        STA YOUSHP                  ; set player shape
        JMP REDRAWCHECK             ; process redraw

; Move down - check bottom boundary (Y = $AA = 170)
MOVDO:
        LDA YOUY                    ; get Y position
        CMP #$AA                    ; at bottom boundary?
        BEQ REDRAWCHECK             ; yes, can't move
        INC YOUY                    ; move down
        LDA #$00                    ; facing down sprite
        STA YOUSHP                  ; set player shape
        JMP REDRAWCHECK             ; process redraw

; Move left - check left boundary (X = 6)
MOVLE:
        LDA YOUX                    ; get X position
        CMP #$06                    ; at left boundary?
        BEQ REDRAWCHECK             ; yes, can't move
        DEC YOUX                    ; move left
        LDA #$08                    ; facing left sprite
        STA YOUSHP                  ; set player shape
        JMP REDRAWCHECK             ; process redraw

; Move right - check right boundary (X = $8F = 143)
MOVRI:
        LDA YOUX                    ; get X position
        CMP #$8F                    ; at right boundary?
        BEQ L_7391                  ; yes, can't move
        INC YOUX                    ; move right
        LDA #$08                    ; facing right sprite
        STA YOUSHP                  ; set player shape
L_7391:
        JMP REDRAWCHECK             ; process redraw


; ----------------------------------------------------------------
; DRAWYOU - Draw player sprite with collision detection
; Alternates between walk frames based on Y position
; Checks collision via REPORT, calls SOUNDTICK on hit
; ----------------------------------------------------------------
DRAWYOU:
        LDA SHAPE                   ; get current shape
        BNE L_73A2                  ; non-zero, use as-is
        ; Animate walk cycle based on Y position
        LDA Y                       ; get Y coordinate
        LSR A                       ; divide by 4
        LSR A                       ;
        BCC L_73A2                  ; even = shape 0
        LDA #$04                    ; odd = shape 4 (walk frame)
        STA SHAPE                   ; set alternate frame
L_73A2:
        JSR DRAW2                   ; draw sprite with collision
        LDA REPORT                  ; get collision result
        AND FLAG                    ; mask with collision enable
        BEQ L_73B7                  ; no collision, return
        ; Collision detected - play tick and check time
        JSR SOUNDTICK               ; tick timer
        BCC L_73B7                  ; time remaining, continue
        ; Time expired - player dies
        LDA #$00                    ; clear hits
        STA YOUHITS                 ; player dead
        JMP YOUDIED                 ; handle death

L_73B7:
        RTS                         ; return

; ----------------------------------------------------------------
; ERASEYOU - Erase player sprite at current position
; Uses XOR drawing to toggle sprite off
; ----------------------------------------------------------------
ERASEYOU:
        LDA YOUSHP                  ; get player sprite
        STA SHAPE                   ; set for draw
        LDA #$FF                    ; white color (XOR erases)
        STA COLOR                   ;
        LDA YOUX                    ; get player X
        STA X                       ; set draw X
        LDA YOUY                    ; get player Y
        STA Y                       ; set draw Y
        LDA #$00                    ; disable collision check
        STA FLAG                    ;
        JMP DRAWYOU                 ; draw (XOR = erase)

; ----------------------------------------------------------------
; SNOOKHIT - Player was hit by enemy cat
; Decrements hits, respawns at random position
; ----------------------------------------------------------------
SNOOKHIT:
        STX XSAVE                   ; save X register
        DEC YOUHITS                 ; decrement hit points
        BEQ YOUDIED                 ; no hits left = death
        JSR PUTHITS                 ; update hit display
        LDA FLAG                    ; save collision state
        STA FLAGSAVE                ;
SNOOKHIT1:
        JSR ERASEYOU                ; erase current sprite

; Respawn at new random position
RESPAWN:
        INC COUNT                   ; advance random counter
        LDY COUNT                   ; use as index
        LDA $F100,Y                 ; random X from ROM
        CLC                         ;
        ADC #$0C                    ; offset from left
        AND #$7F                    ; mask to playfield
        STA YOUX                    ; set new X
        LDA $F200,Y                 ; random Y from ROM
        AND #$7F                    ; mask to playfield
        CLC                         ;
        ADC #$1E                    ; offset from top
        STA YOUY                    ; set new Y

; Check if respawn position is clear
RESPAWN1:
        JSR ERASEYOU                ; draw at new position
        LDA REPORT                  ; check for collision
        BEQ FLASHYOU                ; clear, do flash animation
RESPAWN2:
        ; Position blocked, try again
        JSR ERASEYOU                ; erase
        JMP RESPAWN                 ; get new random position


; ----------------------------------------------------------------
; YOUDIED - Player death handler
; Decrements lives, flashes sprite, plays death sound
; If lives remain: respawn at new level. Otherwise: game over.
; ----------------------------------------------------------------
YOUDIED:
        DEC YOULIVES                ; decrement lives
        BNE CONTDIE                 ; lives left, continue

        ; No more lives - GAME OVER
        PLA                         ; clean up stack
        PLA                         ;
        PLA                         ;
        PLA                         ;
        JSR ERASEYOU                ; erase player sprite
        JSR PUTHITS                 ; update display
STILMOR:
        JSR PUTLIVES                ; show 0 lives
        LDA #$FF                    ; max Y for sound pitch
        STA Y                       ;
        LDA #$00                    ; min X for sound
        STA X                       ;
        JMP TWOTONE                 ; play game over sound

; Lives remaining - respawn
CONTDIE:
        PLA                         ; clean up stack
        PLA                         ;
        PLA                         ;
        PLA                         ;
        JSR ERASEYOU                ; erase player sprite
CONTDIE1:
        JSR PUTHITS                 ; update display
        JSR PUTLIVES                ; show remaining lives
        LDA #$03                    ; reset hit points
        STA YOUHITS                 ; full health
        LDA #$FF                    ; sound pitch parameters
        STA Y                       ;
        LDA #$00                    ;
        STA X                       ;
        JSR TWOTONE                 ; play death sound
        JMP LEVELINIT               ; restart level

; ----------------------------------------------------------------
; FLASHYOU - Flash respawned player for visibility
; Cycles through colors with increasing brightness
; ----------------------------------------------------------------
FLASHYOU:
        JSR ERASEYOU                ; ensure sprite drawn
        LDA #$01                    ; start with darkest color
        STA COLOR                   ;
L_7446:
        LDA YOUSHP                  ; get player sprite
        STA SHAPE                   ;
        LDA YOUX                    ; get position
        STA X                       ;
        LDA YOUY                    ;
        STA Y                       ;
        LDA #$00                    ; no collision check
        STA FLAG                    ;
FLASHDRAW:
        JSR DRAWYOU                 ; draw with current color
        LDA #$60                    ; delay for flash timing
        JSR WAIT                    ; wait
        ASL COLOR                   ; shift color left (brighter)
        BCC L_7446                  ; continue until bit falls off

DEATHWAIT:
        STA KBDSTRB                 ; clear keyboard strobe
        JSR DEATHSOUND              ; play death sound
        JMP TWOTONE2                ; continue sound

; ----------------------------------------------------------------
; Two-tone sound effect generator
; Creates ascending/descending frequency beeps
; X/Y control pitch, loops for duration
; ----------------------------------------------------------------
DEATHSOUND:
        LDA #$00                    ; low pitch
        STA X                       ;
        LDA #$40                    ; medium pitch
        STA Y                       ;
TWOTONE:
        LDX #$06                    ; 6 outer iterations
L_7475:
        LDY X                       ; get delay from X
L_7477:
        DEY                         ; inner delay loop
        BNE L_7477                  ; wait
        LDA SOUND                   ; check sound enabled
        BMI L_7481                  ; bit 7 = muted
        STA SPKR                    ; toggle speaker
L_7481:
        DEX                         ; next iteration
        BNE L_7475                  ; continue tone
        LDX #$06                    ; reset for second frequency
; Second frequency sweep (Y register controls pitch)
L_7486:
        LDY Y                       ; get second pitch
L_7488:
        DEY                         ; inner delay loop
        BNE L_7488                  ; wait
        LDA SOUND                   ; check sound enabled
        BMI L_7492                  ; bit 7 = muted
        STA SPKR                    ; toggle speaker
L_7492:
        DEX                         ; next iteration
        BNE L_7486                  ; continue tone
        INC X                       ; increase first pitch
        DEC Y                       ; decrease second pitch
        LDA Y                       ; check if done
        BNE TWOTONE                 ; continue sweeping
        RTS                         ; return

; Resume after death sound, reset cat state
TWOTONE2:
        LDX XSAVE                   ; restore X register
        LDA #$7F                    ; white color
        STA COLOR                   ;
        LDA FLAGSAVE                ; restore collision flag
        STA FLAG                    ;
        JMP CATRESET                ; reset cat positions


; ----------------------------------------------------------------
; INITCAT - Initialize enemy cats at level start
; Sets position from PLACESX/PLACESY tables,
; direction to 1 (moving right), walk counter to 5
; ----------------------------------------------------------------
INITCAT:
        LDX NUMCATS                 ; get number of cats
L_74AD:
        ; Initialize each cat's state
        LDA #$05                    ; initial walk counter
        STA CATWALK,X               ; set walk delay
        STA CATUSE,X                ; mark cat as active
        LDA PLACESX,X               ; get spawn X from table
        STA CATX,X                  ; set cat X position
        LDA PLACESY,X               ; get spawn Y from table
        STA CATY,X                  ; set cat Y position
        LDA #$01                    ; initial direction = right
        STA CATDIR,X                ; set cat direction
        DEX                         ; next cat
        BPL L_74AD                  ; loop for all cats

; Clear food array and draw all cats
INITCATDRAW:
        LDX #$07                    ; 8 food slots
L_74C6:
        LDA #$00                    ; clear food position
        STA FOODX,X                 ;
        DEX                         ; next slot
        BPL L_74C6                  ; loop until done

        ; Draw all cats at their starting positions
        LDX NUMCATS                 ; get cat count
L_74CF:
        LDA CATX,X                  ; get cat X
        STA X                       ; set draw X
        LDA CATY,X                  ; get cat Y
        STA Y                       ; set draw Y
        JSR DRAWCAT                 ; draw cat sprite
        DEX                         ; next cat
        BPL L_74CF                  ; loop for all
        RTS                         ; return


; ----------------------------------------------------------------
; DRAWCAT - Enemy sprite rendering
; Selects shape based on CATDIR bit 0 (left/right facing)
; bit 0 = 1: facing left (shape $10)
; bit 0 = 0: facing right (shape $0C)
; ----------------------------------------------------------------
DRAWCAT:
        LDA CATDIR,X                ; get cat direction
        LSR A                       ; shift bit 0 into carry
        BCC L_74E9                  ; carry clear = facing right
        LDA #$10                    ; facing left sprite
        STA SHAPE                   ;
        BNE L_74ED                  ; (always taken)
L_74E9:
        LDA #$0C                    ; facing right sprite
        STA SHAPE                   ;
L_74ED:
        LDA #$7F                    ; white color for cat sprite
        STA COLOR                   ;
        STX XSAVE                   ; save cat index
        LDA #$FF                    ; enable collision detection
        STA $20                     ; collision flag on
        JSR DRAW2                   ; draw cat sprite with XOR
        LDA #$00                    ; disable collision detection
        STA $20                     ; collision flag off
        LDX XSAVE                   ; restore cat index
        ; --- Check if cat is eating food ---
        LDA FOODC                   ; is food active?
        BEQ L_752F                  ; no food, skip check
        ; Compare cat position to food position (coarse grid)
        LDA CATX,X                  ; get cat X
        AND #$E0                    ; mask to grid cell (32 pixels)
        STA $00                     ; save cat grid X
        LDA $7B                     ; get food X
        AND #$E0                    ; mask to grid cell
        STA $02                     ; save food grid X
        LDA CATY,X                  ; get cat Y
        AND #$E0                    ; mask to grid cell
        STA $01                     ; save cat grid Y
        LDA $7C                     ; get food Y
        AND #$E0                    ; mask to grid cell
        STA COLORMASK               ; save food grid Y
        LDA $00                     ; compare X positions
        CMP $02                     ;
        BNE L_752F                  ; X doesn't match, not eating
        LDA $01                     ; compare Y positions
        CMP COLORMASK               ;
        BNE L_752F                  ; Y doesn't match, not eating
        ; Cat is eating the food!
        LDA #$00                    ; clear collision report
        STA REPORT                  ;
        STA $7A                     ; flag = food eaten
        RTS

L_752F:
        LDA #$07                    ; normal status (not eating)
        STA $7A                     ;
        RTS

; ----------------------------------------------------------------
; DRAWCATWRITE - Draw cat directly (non-XOR write mode)
; Used when cat changes direction against wall
; Same sprite selection as DRAWCAT but uses STABW2
; ----------------------------------------------------------------
DRAWCATWRITE:
        LDA CATDIR,X                ; get cat direction
        LSR A                       ; shift bit 0 (left/right) into carry
        BCC L_753F                  ; carry clear = facing right
        LDA #$10                    ; facing left sprite (shape $10)
        STA SHAPE                   ;
        BNE L_7543                  ; (always taken)
L_753F:
        LDA #$0C                    ; facing right sprite (shape $0C)
        STA SHAPE                   ;
L_7543:
        LDA #$7F                    ; white color
        STA COLOR                   ;
        STX XSAVE                   ; save cat index
        LDA #$FF                    ; enable collision detection
        STA $20                     ;
        JSR STABW2                  ; direct write (not XOR)
        LDA #$00                    ; disable collision detection
        STA $20                     ;
        LDX XSAVE                   ; restore cat index
        RTS


; ----------------------------------------------------------------
; CATDIR_AI - Cat direction decision
; Compares cat position to player position
; Sets CATDIR bits: 0=left/right, 1=up, 2=down
; Enemies actively chase the player
; ----------------------------------------------------------------

CATDIR_AI:
        ; --- Determine horizontal chase direction ---
        LDA YOUX                    ; get player X position
        CMP CATX,X                  ; compare to cat X
        BMI L_7569                  ; player left of cat -> chase left (bit0=1)
        BEQ L_7565                  ; same X -> pause movement
        ; Player is right of cat
        LDA #$00                    ; bit0=0: move right
        STA CATDIR,X                ;
        BEQ L_756D                  ; (always) now check vertical
L_7565:
        ; Same X as player - add walk delay
        LDA #$14                    ; delay = 20 frames
        STA CATWALK,X               ; pause horizontal pursuit
L_7569:
        ; Player is left of cat
        LDA #$01                    ; bit0=1: move left
        STA CATDIR,X                ;
L_756D:
        ; --- Determine vertical chase direction ---
        LDA YOUY                    ; get player Y position
        CMP CATY,X                  ; compare to cat Y
        BCC L_757D                  ; player above cat -> chase up (bit1=1)
        BEQ L_7583                  ; same Y -> no vertical movement
        ; Player is below cat
        LDA #$04                    ; bit2=1: move down
        ORA CATDIR,X                ; combine with horizontal direction
        STA CATDIR,X                ;
        BNE L_7583                  ; (always) continue to movement
L_757D:
        ; Player is above cat
        LDA #$02                    ; bit1=1: move up
        ORA CATDIR,X                ; combine with horizontal direction
        STA CATDIR,X                ;
L_7583:
        JMP CATMOVE                 ; apply movement from direction bits

L_7586:
        JMP SKIPCAT                 ; skip inactive cat


; ----------------------------------------------------------------
; UPCAT - Update all active enemy cats
; Main enemy AI loop: move, check collisions, handle death
; Converts dead cats to food items
; Direction bits: 0=left/right, 1=up, 2=down
; ----------------------------------------------------------------

UPCAT:
        LDX NUMCATS                 ; start with highest cat index
        LDA #$08                    ; max 8 cats
        STA CATCOUNT                ; initialize cat counter
        LDA #$00                    ; clear flag
        STA FLAG                    ; no collision yet
UPCATLOOP:
        LDA CATUSE,X                ; is this cat active?
        BEQ L_7586                  ; no -> skip to next cat
        ; Save current cat state before movement
        LDA CATX,X                  ; save old X position
        STA TEMPX                   ;
        LDA CATY,X                  ; save old Y position
        STA FLAG                    ; also flags cat as processed
        STA TEMPY                   ;
        LDA CATDIR,X                ; save old direction
        STA TEMPSHP                 ;
        ; Check walk delay counter
        LDA CATWALK,X               ; walk delay active?
        BEQ CATDIR_AI               ; no -> recalculate AI direction
        DEC CATWALK,X               ; decrement delay counter
; ----------------------------------------------------------------
; CATMOVE - Apply direction bits to cat position
; bit 0: 0=move right (INC X), 1=move left (DEC X)
; bit 1: 1=move up (DEC Y)
; bit 2: 1=move down (INC Y)
; ----------------------------------------------------------------
CATMOVE:
        LDA CATDIR,X                ; get direction bits
        LSR A                       ; shift bit 0 into carry
        BCS L_75B4                  ; carry set = move left
        INC CATX,X                  ; move right (bit0=0)
        BNE L_75B6                  ; (always taken)
L_75B4:
        DEC CATX,X                  ; move left (bit0=1)
L_75B6:
        LSR A                       ; shift bit 1 into carry
        BCC L_75BB                  ; carry clear = no up movement
        DEC CATY,X                  ; move up (bit1=1)
L_75BB:
        LSR A                       ; shift bit 2 into carry
        BCC L_75C0                  ; carry clear = no down movement
        INC CATY,X                  ; move down (bit2=1)
L_75C0:
        ; --- Erase cat at old position, draw at new ---
        LDA CATDIR,X                ; save new direction
        PHA                         ;
        LDA TEMPX                   ; set draw coords to old position
        STA X                       ;
        LDA TEMPY                   ;
        STA Y                       ;
        LDA TEMPSHP                 ; restore old direction for erase
        STA CATDIR,X                ; (affects sprite selection)
CATERASE:
        JSR DRAWCAT                 ; XOR erase old sprite
        PLA                         ; restore new direction
        STA CATDIR,X                ;
        LDA CATX,X                  ; set draw coords to new position
        STA X                       ;
        LDA CATY,X                  ;
        STA Y                       ;
CATREDRAW:
        JSR DRAWCAT                 ; XOR draw new sprite
        ; Check collision result from DRAWCAT
        LDA $7A                     ; collision status
        BNE L_75E7                  ; nonzero = collision detected
        JMP CATDEATHSND             ; zero = cat ate food, play sound

; --- Boundary detection for cat movement ---
L_75E7:
        LDA CATX,X                  ; check cat X position
        CMP #$04                    ; at left boundary?
        BEQ L_7608                  ; yes -> horizontal wall hit
        CMP #$8C                    ; at right boundary? ($8C = 140)
        BEQ L_7608                  ; yes -> horizontal wall hit
        LDA CATY,X                  ; check cat Y position
        CMP #$14                    ; at top boundary? ($14 = 20)
        BEQ L_760E                  ; yes -> vertical wall hit
        CMP #$AA                    ; at bottom boundary? ($AA = 170)
        BEQ L_760E                  ; yes -> vertical wall hit
        ; No boundary collision - check sprite collision
        LDA #$02                    ; ASAVE1=2 for no wall hit
        STA ASAVE1                  ;
        LDA REPORT                  ; check collision report from XOR draw
        BEQ SKIPCAT                 ; no collision -> process next cat
        BPL L_7614                  ; positive = hit something else
CATHITYOU:
        JMP SNOOKHIT                ; negative = hit player! damage!

L_7608:
        ; Cat hit horizontal wall (left or right)
        LDA #$00                    ; ASAVE1=0 for horizontal wall
        STA ASAVE1                  ;
        BEQ CATRESET                ; (always) reverse direction
L_760E:
        ; Cat hit vertical wall (top or bottom)
        LDA #$01                    ; ASAVE1=1 for vertical wall
        STA ASAVE1                  ;
        BNE CATRESET                ; (always) reverse direction
L_7614:
        ; Collision detected but not with player
        LDA $7A                     ; check food-eating flag
        BNE L_761B                  ; nonzero = didn't eat food
CATNOWALL:
        JMP CATDEATHSND             ; zero = cat ate food

L_761B:
        ; Random chance to change direction when hitting obstacle
        INC COUNT                   ; increment random counter
        LDY COUNT                   ;
        LDA $F000,Y                 ; get pseudo-random value from ROM
        AND $7A                     ; mask with collision flags
        BEQ CATRESET                ; zero = don't redraw
        ; Redraw cat at current position
        LDA CATX,X                  ;
        STA X                       ;
        LDA CATY,X                  ;
        STA Y                       ;
        JSR DRAWCATWRITE            ; direct write (not XOR)
CATFINISH:
        JMP CATRESET                ; continue to direction reset

; --- Loop control for cat processing ---
SKIPCAT:
        DEX                         ; next cat index
        BPL L_763F                  ; more cats -> continue loop
        LDA FLAG                    ; any cats processed?
        BEQ L_763C                  ; no -> level finished
        RTS                         ; return to main loop

L_763C:
        JMP FINISHED                ; all enemies dead -> level complete

L_763F:
        JMP UPCATLOOP               ; process next cat

; ----------------------------------------------------------------
; CATRESET - Reverse cat direction after wall collision
; Uses ASAVE1 (0=horiz, 1=vert, 2=other) to flip direction bits
; Also sets random walk delay before next AI recalculation
; ----------------------------------------------------------------
CATRESET:
        LDA CATX,X                  ; save current position
        STA TEMPX                   ;
        STA X                       ; also set draw position
        LDA CATY,X                  ;
        STA TEMPY                   ;
        STA Y                       ;
        LDA CATDIR,X                ; get current direction
        STA TEMPSHP                 ; save for later
        ; Flip direction based on wall type
        LDY ASAVE1                  ; 0=horiz wall, 1=vert wall
        EOR $7017,Y                 ; XOR with flip table
        STA CATDIR,X                ; store new direction
        ; Calculate random walk delay
        TXA                         ; cat index
        ADC TIME                    ; add game timer for randomness
        LSR A                       ; divide by 8
        LSR A                       ;
        LSR A                       ;
        TAY                         ;
        LDA $F800,Y                 ; get pseudo-random from ROM
        AND #$1F                    ; mask to 0-31
        ORA #$05                    ; ensure minimum delay of 5
        STA CATWALK,X               ; set walk delay counter
        DEC CATCOUNT                ; decrement cats remaining
        LDA CATCOUNT                ;
; ----------------------------------------------------------------
; CATHITSND - Short click sound when cat bounces off wall
; ----------------------------------------------------------------
CATHITSND:
        BMI CATDEATHSND             ; all cats done -> skip sound
        STX XSAVE                   ; save cat index
        LDX #$03                    ; 3 sound iterations
L_7673:
        ; Generate variable frequency based on cat index
        LDA XSAVE                   ; cat index
        ROL A                       ; rotate and shift
        ASL A                       ;
        ASL A                       ;
        ASL A                       ;
        EOR COUNT                   ; XOR with counter for variation
        TAY                         ; use as delay
L_767C:
        DEY                         ; inner delay loop
        BNE L_767C                  ;
        LDA SOUND                   ; check if sound enabled
        BMI L_7686                  ; bit 7 set = muted
        STA SPKR                    ; toggle speaker
L_7686:
        INC COUNT                   ; vary next iteration
        DEX                         ; next sound iteration
        BNE L_7673                  ; continue sound loop
        LDX XSAVE                   ; restore cat index
        JMP CATMOVE                 ; continue cat movement

; ----------------------------------------------------------------
; CATDEATHSND - Descending tone when cat dies
; Creates falling pitch by nested loops with decreasing outer count
; After sound, converts dead cat into food item
; ----------------------------------------------------------------
CATDEATHSND:
        LDA #$7F                    ; start with high pitch (127 cycles)
        STA $00                     ; outer loop counter (pitch)
L_7694:
        LDA $00                     ; copy to inner counter
        STA $01                     ;
L_7698:
        DEC $01                     ; inner delay loop
        BNE L_7698                  ; wait for pitch period
        LDA SOUND                   ; check if sound enabled
        BMI L_76A3                  ; bit 7 set = muted
        STA SPKR                    ; toggle speaker
L_76A3:
        DEC $00                     ; lower the pitch
        BNE L_7694                  ; continue until pitch = 0
        ; --- Cat is now dead - convert to food item ---
        LDA #$00                    ; mark cat as inactive
        STA CATUSE,X                ;
        LDA TEMPSHP                 ; restore original direction
        STA CATDIR,X                ; for final erase
        LDA CATX,X                  ; set draw position
        STA X                       ;
        LDA CATY,X                  ;
        STA Y                       ;
CATDRAW3:
        JSR DRAWCAT                 ; XOR erase cat sprite
        ; --- Create food item at cat's death location ---
        LDA CATX,X                  ; save X position
        STA FOODY,X                 ; (note: uses FOODY for X coord storage)
        LDA #$01                    ; mark food slot as active
CATTOFOOD:
        STA FOODX,X                 ; food is now present
        LDA CATY,X                  ; save Y position
        STA $CB,X                   ; food Y coordinate
        LDA #$00                    ; initial bounce direction = up
        STA $D3,X                   ; bounce state (0=up, $80=down)
        ; Set up food sprite drawing
        LDA FOODY,X                 ; get food X
        STA TEMPX                   ;
        LDA $CB,X                   ; get food Y
        STA TEMPY                   ;
        LDA $D3,X                   ; get bounce state
        STA TEMPSHP                 ;
FOODDRAW1:
        JSR DRAWFOOD                ; draw food sprite
        TXA                         ; save cat/food index
        PHA                         ;
        LDA #$50                    ; 50 points for killing cat
        JSR ADDSCORE                ; add to score (BCD)
        PLA                         ; restore index
        TAX                         ;
        JMP SKIPCAT                 ; continue to next cat

; --- Food animation loop control ---
FOODDONE:
        DEX                         ; next food slot
        BPL L_76EB                  ; more slots -> continue
        RTS                         ; all food processed


; ----------------------------------------------------------------
; FOODANIM - Animate bouncing food items
; Food bounces up and down between Y=$12 (top) and Y=$AA (bottom)
; $D3,X = bounce direction: 0 = moving up, $80 = moving down
; Creates visual "bouncing" effect for dropped food
; ----------------------------------------------------------------

FOODANIM:
        LDX #$07                    ; start with food slot 7
L_76EB:
        LDA FOODX,X                 ; is this food slot active?
        BEQ FOODDONE                ; no -> try next slot
        ; Load current food state
        LDA FOODY,X                 ; food X position
        STA TEMPX                   ;
        LDA $CB,X                   ; food Y position
        STA TEMPY                   ;
        LDA $D3,X                   ; bounce direction
        STA TEMPSHP                 ;
        ; --- Update bounce position ---
        BNE L_770D                  ; nonzero = moving down
        ; Moving up (direction = 0)
        DEC $CB,X                   ; move up 2 pixels
        DEC $CB,X                   ;
        LDA $CB,X                   ; check if hit top
        CMP #$12                    ; top boundary
        BCS L_771B                  ; not at top yet -> draw
        LDA #$80                    ; reverse: now moving down
        STA $D3,X                   ;
        BNE L_771B                  ; (always) draw food
L_770D:
        ; Moving down (direction = $80)
        INC $CB,X                   ; move down 2 pixels
        INC $CB,X                   ;
        LDA $CB,X                   ; check if hit bottom
        CMP #$AA                    ; bottom boundary ($AA = 170)
        BCC L_771B                  ; not at bottom yet -> draw
        LDA #$00                    ; reverse: now moving up
        STA $D3,X                   ;
L_771B:
        ; --- Erase old position and draw new ---
        JSR DRAWFOOD                ; XOR erase at old position
        LDA FOODY,X                 ; X position (unchanged)
        STA TEMPX                   ;
        LDA $CB,X                   ; new Y position
        STA TEMPY                   ;
        LDA $D3,X                   ; bounce direction
        STA TEMPSHP                 ;
        JSR DRAWFOOD                ; XOR draw at new position
        LDA TEMPSHP                 ; save bounce direction
        STA $D3,X                   ;
        JMP FOODDONE                ; continue to next food slot

; ----------------------------------------------------------------
; DRAWFOOD - Draw food sprite with animation frame
; Uses Y position bits to select between 3 food shapes
; This creates a "tumbling" animation as food bounces
; Shapes: $20, $24, $28 (selected by Y position mod 4)
; ----------------------------------------------------------------
DRAWFOOD:
        LDA #$7F                    ; white color for food
        STA COLOR                   ;
        LDA TEMPX                   ; set X position
        STA X                       ;
        LDA TEMPY                   ; set Y position
        STA Y                       ;
        ; Select animation frame based on Y position
        LSR A                       ; divide Y by 2
        AND #$03                    ; mod 4 -> 0,1,2,3
        BEQ L_775A                  ; 0 -> shape $24
        TAY                         ; use as counter
        DEY                         ;
        BEQ L_7753                  ; 1 -> shape $20
        DEY                         ;
        BEQ L_775A                  ; 2 -> shape $24
        ; 3 -> shape $28
        LDA #$28                    ; food animation frame 3
        STA SHAPE                   ;
        JMP DRAWFOODSPRITE          ;

L_7753:
        LDA #$20                    ; food animation frame 1
        STA SHAPE                   ;
        JMP DRAWFOODSPRITE          ;

L_775A:
        LDA #$24                    ; food animation frame 2
        STA SHAPE                   ;
DRAWFOODSPRITE:
        STX XSAVE                   ; save food index
        JSR DRAW2                   ; draw with XOR
        LDX XSAVE                   ; restore food index
        RTS


; ----------------------------------------------------------------
; FINISHED - Level completion celebration
; Adds 1 point per loop and plays sound until timer expires
; Player has killed all cats to reach this point
; ----------------------------------------------------------------
FINISHED:
        LDA #$01                    ; add 1 point
        JSR ADDSCORE                ; to score
        JSR SOUNDTICK               ; play tick and check timer
        BCS L_777A                  ; carry set = time's up
        JSR SOUNDTICK               ; keep playing
        BCS L_777A                  ;
        JSR SOUNDTICK               ;
        BCC FINISHED                ; carry clear = continue
L_777A:
        RTS                         ; level done

; ----------------------------------------------------------------
; ADDSCORE - Add A to score using BCD arithmetic
; 3-byte BCD score: SCORELO, SCOREHI, SCOREHI1
; Each byte holds 2 BCD digits (00-99)
; Total range: 000000 to 999999 points
; ----------------------------------------------------------------
ADDSCORE:
        SED                         ; enable BCD mode
        CLC                         ; clear carry for add
        ADC SCORELO                 ; add to low byte
        STA SCORELO                 ;
        BCC L_7792                  ; no overflow -> done
        CLC                         ; carry into middle byte
        LDA SCOREHI                 ;
        ADC #$01                    ; add 1 (the carry)
        STA SCOREHI                 ;
        BCC L_7792                  ; no overflow -> done
        LDA SCOREHI1                ; carry into high byte
        ADC #$01                    ;
        STA SCOREHI1                ;
L_7792:
        CLD                         ; disable BCD mode
        JMP PUTSCORE                ; update score display


; ----------------------------------------------------------------
; LEVELSTART - Game initialization entry point
; Sets YOUHITS=3 (player hit points per level)
; Calculates NUMCATS from LEVEL: (LEVEL/4 & 3) + 1
;   Level 0-3: 1 cat, Level 4-7: 2 cats,
;   Level 8-11: 3 cats, Level 12+: 4 cats (max)
; Falls through to LEVELINIT
;
; LEVELINIT - Set up screen, enemies, player position
; Main game loop at MAINLOOP:
;   - 32 frames per outer loop iteration
;   - Checks keyboard for pause (ESC) and sound toggle (Ctrl-S)
;   - Updates enemies and player positions
;   - Speed scaling: level < 15 gives player more updates
;                    level >= 15 gives enemies more updates (harder!)
; ----------------------------------------------------------------

LEVELSTART:
        LDA #$03                    ; 3 hit points per level
        STA YOUHITS                 ;
        LDA LEVEL                   ; calculate number of cats
        LSR A                       ; level / 4
        LSR A                       ;
        AND #$03                    ; limit to 0-3
        STA NUMCATS                 ;
        INC NUMCATS                 ; +1 -> 1-4 cats
LEVELINIT:
        ; --- Draw play area border and status ---
        JSR BORDER                  ; draw screen border
        JSR PUTSCORE                ; display score
        JSR PUTLIVES                ; display remaining lives
        JSR PUTHITS                 ; display hit points
        ; --- Initialize game state variables ---
        LDA #$00                    ; no food active initially
        STA FOODC                   ;
        LDA #$C0                    ; level timer = 192 frames
        STA YSAVE                   ; (counts down to 0)
        LDA #$80                    ; initialize food position
        STA $7B                     ; food X = center
        STA $7C                     ; food Y = center
        ; --- Set player starting position ---
        LDA #$28                    ; player X = 40
        STA YOUX                    ;
        STA X                       ; set draw X
        LDA #$3C                    ; player Y = 60
        STA YOUY                    ;
        STA Y                       ; set draw Y
        LDA #$00                    ; player shape = 0 (neutral)
        STA YOUSHP                  ;
        STA SHAPE                   ;
        LDA #$FF                    ; white color for player
        STA COLOR                   ;
DRAWPLAYER:
        JSR DRAW2                   ; draw player at start position
        ; --- Place initial food items ---
        LDA #$06                    ; place 6 food items
L_77D9:
        STA ASAVE                   ; save food counter
PLACEFOODINIT:
        JSR PLACEFOOD               ; place one food item
        LDA ASAVE                   ; decrement counter
        TAY                         ;
        DEY                         ;
        TYA                         ;
        BNE L_77D9                  ; more food -> loop
INITCATS2:
        JSR INITCAT                 ; initialize enemy cats

; ================================================================
; MAINLOOP - Core game loop (runs continuously during play)
; Processes 32 sub-frames per outer iteration
; ================================================================
MAINLOOP:
        LDA #$20                    ; 32 sub-frames per loop
MAINLOOPINNER:
        STA ASAVE                   ; save frame counter
        ; --- Check for special keys ---
        LDA KEYBOARD                ; read keyboard
        CMP #$93                    ; Ctrl-S?
        BEQ FIXSOUND                ; toggle sound
        CMP #$9B                    ; ESC (Ctrl-[)?
        BNE NOKEY                   ; no special key
PAUSELOOP:
        STA KBDSTRB                 ; clear keyboard strobe
PAUSEWAIT:
        LDA KEYBOARD                ; wait for keypress to resume
        BPL PAUSEWAIT               ; loop until key pressed
        STA KBDSTRB                 ; clear strobe
        BNE NOKEY                   ; (always) continue game
FIXSOUND:
        LDA SOUND                   ; toggle sound enable
        EOR #$80                    ; flip bit 7
        STA SOUND                   ;
NOKEY:
        ; --- Check demo mode and exit key ---
        LDA DEMO                    ; in demo mode?
        BNE L_7813                  ; yes -> skip exit check
        LDA KEYBOARD                ; any key pressed?
        BMI L_784F                  ; yes -> exit to DOS
L_7813:
        ; --- Update game entities ---
        JSR UPDATEENEMIES           ; move/draw enemies
        ; Speed scaling based on level
        LDA LEVEL                   ; check level number
        CMP #$0F                    ; level >= 15?
        BCS L_7822                  ; yes -> hard mode (more enemy updates)
        ; Easy mode: extra player update
        JSR UPDATEPLAYER            ; normal player update
        JMP MAINLOOPTIMING          ; continue to timing

L_7822:
        ; Hard mode (level 15+): enemies get 3x updates, player gets 2x
        JSR UPDATEENEMIES           ; extra enemy update
        JSR UPDATEENEMIES           ; extra enemy update
        JSR UPDATEPLAYER            ; player update
        JSR UPDATEPLAYER            ; extra player update
MAINLOOPTIMING:
        ; --- Frame timing and food spawning ---
        DEC YSAVE                   ; decrement level timer
        LDA YSAVE                   ;
        BEQ L_7852                  ; timer=0 -> spawn new food
        AND #$1F                    ; every 32 frames...
        BEQ L_7887                  ; ...toggle food visibility
PAGESETUP:
        ; --- Inner loop control ---
        LDA ASAVE                   ; decrement frame counter
        TAY                         ;
        DEY                         ;
        TYA                         ;
        BNE MAINLOOPINNER           ; more frames -> continue
        ; --- Outer loop: check timer ---
        JSR SOUNDTICK               ; tick sound and check timeout
        BCC MAINLOOP                ; carry clear -> continue playing
        ; Time's up! Player loses
        LDA #$00                    ; clear hit points
        STA YOUHITS                 ;
        PHA                         ; push placeholder values
        PHA                         ;
        PHA                         ;
        PHA                         ;
        JMP YOUDIED                 ; handle death sequence

L_784F:
        JMP $0803                   ; exit to DOS loader

; --- Food spawning when level timer expires ---
L_7852:
        LDA #$00                    ; deactivate current food
        STA FOODC                   ;
        JSR DRAWFOODAT              ; erase food sprite
PAGEINIT1:
        ; Generate random position for new food
        INC COUNT                   ; increment random counter
        LDY COUNT                   ;
        LDA $F000,Y                 ; pseudo-random X from ROM
        CLC                         ;
        ADC #$14                    ; offset from edge
        AND #$7F                    ; limit to 0-127
        STA $7B                     ; new food X
        LDA $F200,Y                 ; pseudo-random Y from ROM
        AND #$7F                    ; limit to 0-127
        ADC #$28                    ; offset from top
        STA $7C                     ; new food Y
        LDA #$7F                    ; activate food
        STA FOODC                   ;
        JSR DRAWFOODAT              ; draw food sprite
        LDA REPORT                  ; check collision with existing sprite
        BEQ L_7881                  ; no collision -> continue
        JSR DRAWFOODAT              ; collision! erase and try again
        JMP PAGEINIT1               ; pick new position

L_7881:
        JSR DRAWFOODAT              ; redraw food (XOR toggle)
        JMP PAGESETUP               ; continue game loop

; --- Food flashing effect (every 32 frames) ---
L_7887:
        JSR DRAWFOODAT              ; XOR toggle food visibility
        LDA FOODC                   ; toggle food active flag
        EOR #$7F                    ; flip between $00 and $7F
        STA FOODC                   ;
        JMP PAGESETUP               ; continue game loop

; ----------------------------------------------------------------
; DRAWFOODAT - Draw food sprite at current food position ($7B, $7C)
; Uses shape $14 (food shape) with white color
; ----------------------------------------------------------------
DRAWFOODAT:
        LDA #$14                    ; food shape
        STA SHAPE                   ;
        LDA $7B                     ; food X position
        STA X                       ;
        LDA $7C                     ; food Y position
        STA Y                       ;
        LDA #$7F                    ; white color
        STA COLOR                   ;
        JMP DRAW2                   ; draw with XOR

; ----------------------------------------------------------------
; UPDATEENEMIES - Update all enemy cats and animate food
; Calls UPCAT for cat AI, FOODANIM for bouncing food
; Then updates player input
; ----------------------------------------------------------------
UPDATEENEMIES:
        JSR GETTIME                 ; get speed delay for level
        JSR WAIT                    ; ROM delay routine
        JSR UPCAT                   ; update all cat positions
        BCS L_78C0                  ; carry set = level complete
        JSR FOODANIM                ; animate bouncing food items
        JMP UPDATEYOU               ; update player position

; ----------------------------------------------------------------
; UPDATEPLAYER - Update player position only (no enemy update)
; Used for extra player updates on easy levels
; ----------------------------------------------------------------
UPDATEPLAYER:
        JSR GETTIME                 ; get speed delay for level
        JSR WAIT                    ; ROM delay routine
        JMP UPDATEYOU               ; update player position

; --- Level complete: animate remaining food then return ---
L_78C0:
        PLA                         ; discard return address
        PLA                         ;
        LDA #$50                    ; 80 animation frames
L_78C4:
        STA ASAVE                   ; save counter
        JSR FOODANIM                ; animate food
        LDA ASAVE                   ; decrement counter
        TAY                         ;
        DEY                         ;
        TYA                         ;
        BNE L_78C4                  ; continue animation
        RTS                         ; level done


; ----------------------------------------------------------------
; GETTIME - Calculate game speed from level number
; Higher level = lower delay value = faster gameplay
; Formula: ((LEVEL/2) & $0F) XOR $0E) * 2 + 1
; Level 0: delay=29, Level 2: delay=27, ..., Level 28: delay=1
; Returns timing value in A for Monitor WAIT routine ($FCA8)
; ----------------------------------------------------------------

GETTIME:
        LDA LEVEL                   ; get current level
        LSR A                       ; divide by 2
        AND #$0F                    ; limit to 0-15
        EOR #$0E                    ; invert (high level = low value)
        ASL A                       ; multiply by 2
        CLC                         ;
        ADC #$01                    ; add 1 (minimum delay)
        RTS

        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00

; ----------------------------------------------------------------
; Plot vector dispatch table (identical to level1)
; Used by ORPLOTS and PLOTS for single-pixel rendering
; Indexed by plotting mode to select write method
; ----------------------------------------------------------------

DRAWVEC:
        JMP PLOTRTS                 ; mode 0: no-op

        JMP PLOTRTS                 ; mode 1: no-op

DRAWVEC_OR:
        JMP PLOTOR                  ; mode 2: OR plot (additive)

DRAWVEC_DIR:
        JMP PLOTDIRECT              ; mode 3: direct write

        JMP PLOTRTS                 ; mode 4: no-op

; ----------------------------------------------------------------
; PLOTDIRECT - Write pixel directly to both HGR pages
; Uses EOR #$60 trick to write same position on both pages
; Page 1 base = $20, Page 2 base = $40, difference = $60
; ----------------------------------------------------------------
PLOTDIRECT:
        LDY Y                       ; get Y coordinate
        LDX HGRLO,Y                 ; low byte of HGR row address
        LDA $7A11,Y                 ; high byte from lookup table
        STA TOHI                    ; store high byte
        STX TOLO                    ; store low byte
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4 to get byte offset
        LSR A                       ;
        TAY                         ; use as index
        LDA COLOR                   ; get color/pixel pattern
        STA (TOLO),Y                ; write to page 1
        PHA                         ; save color
        LDA TOHI                    ; flip to other page
        EOR #$60                    ; $20 <-> $40
        STA TOHI                    ;
        PLA                         ; restore color
        STA (TOLO),Y                ; write to page 2
        RTS

; ----------------------------------------------------------------
; PLOTOR - OR pixel into both HGR pages (additive drawing)
; Preserves existing pixels, only adds new ones
; ----------------------------------------------------------------
PLOTOR:
        LDY Y                       ; get Y coordinate
        LDX HGRLO,Y                 ; low byte of HGR row address
        LDA $7A11,Y                 ; high byte from lookup table
        STA TOHI                    ; store high byte
        STX TOLO                    ; store low byte
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4 to get byte offset
        LSR A                       ;
        TAY                         ; use as index
        LDA COLOR                   ; get color/pixel pattern
        ORA (TOLO),Y                ; OR with existing pixel
        STA (TOLO),Y                ; write to page 1
        PHA                         ; save result
        LDA TOHI                    ; flip to other page
        EOR #$60                    ; $20 <-> $40
        STA TOHI                    ;
        PLA                         ; restore result
        STA (TOLO),Y                ; write to page 2
PLOTRTS:
        RTS

