; ----------------------------------------------------------------
; XORSCREEN - Visual dissolve/scramble effect (identical to level1)
; XORs each screen byte with its low address byte
; ----------------------------------------------------------------

XORSCREEN:
        LDY #$00
        STY STRLO                   ; $F0
        LDA #$20
        STA STRHI                   ; $F1
L_81A8:
        LDA (STRLO),Y               ; $F0
        EOR STRLO                   ; $F0
        STA (STRLO),Y               ; $F0
        INY
        BNE L_81A8
        INC STRHI                   ; $F1
        LDA STRHI                   ; $F1
        CMP #$40
        BNE L_81A8
        RTS

