        BPL L_8A0C
        .BYTE $80                                  ; |.......|
        STA SHPHI                   ; $15
        LDY #$00
        STY SHPLO                   ; $14
        LDA YY                      ; $1B
L_8A0C:
        STA Y                       ; $19
        LDA #$10
        STA HEIGHT                  ; $1D
L_8A12:
        LDA XX                      ; $1A
        STA X                       ; $18
        LDA (SHPLO),Y               ; $14
        AND COLORMASK               ; $03
        STA COLOR                   ; $11
        STY TEMP9                   ; $09
        JSR NUMGENPLOT              ; $8A3B
        LDY TEMP9                   ; $09
        INY
        LDA (SHPLO),Y               ; $14
        AND COLORMASK               ; $03
        STA COLOR                   ; $11
        STY TEMP9                   ; $09
        INC X                       ; $18
        JSR NUMGENPLOT              ; $8A3B
        LDY TEMP9                   ; $09
        INY
        INC Y                       ; $19
        DEC HEIGHT                  ; $1D
        BNE L_8A12
        RTS

NUMGENPLOT:
        LDA X                       ; $18
        PHA
        ASL A
        ASL A
        STA X                       ; $18
        JSR PLOT2                   ; $9309
        PLA
        STA X                       ; $18
        RTS

