; ----------------------------------------------------------------
; CHRGEN - Large character rendering system (identical to level1)
; Draws multi-pixel text characters with color patterns
; ----------------------------------------------------------------

CHRGEN:
        ASL A
        ASL A
        ASL A
        STA SHPLO                   ; $14
        LDA #$91
        STA SHPHI                   ; $15
        LDA XX                      ; $1A
        STA X                       ; $18
        LDA YY                      ; $1B
        STA Y                       ; $19
        LDA HEIGHT                  ; $1D
        STA $04
        LDY #$00
        STY $00
CHRGENROW:
        LDY $00
        LDA (SHPLO),Y               ; $14
        PHA
CHRGENPIXEL:
        PLA
        PHA
        LDX XX                      ; $1A
        STX X                       ; $18
        LDX #$00
        STX TEMP0F                  ; $0F
        CLC
L_9029:
        LSR A
        BCC L_903B
        STX TEMP9                   ; $09
        PHA
        LDA #$FF
        STA TEMPA                   ; $0A
        JSR CHRGENCOLOR             ; $906B
        LDX TEMP9                   ; $09
        JMP CHRGENNEXT              ; $9047

L_903B:
        STX TEMP9                   ; $09
        PHA
        LDA #$80
        STA TEMPA                   ; $0A
        JSR CHRGENCOLOR             ; $906B
        LDX TEMP9                   ; $09
CHRGENNEXT:
        INX
        PLA
        CPX #$08
        BNE L_9029
        INC Y                       ; $19
        LDA XX                      ; $1A
        STA X                       ; $18
        DEC $04
        BNE L_9065
        LDA HEIGHT                  ; $1D
        STA $04
        PLA
        INC $00
        LDA $00
        CMP #$08
        BNE L_9068
        RTS

L_9065:
        JMP CHRGENPIXEL             ; $901E

L_9068:
        JMP CHRGENROW               ; $9019

CHRGENCOLOR:
        LDA COLORMASK               ; $03
        AND #$7F
        BEQ L_9083
        CMP #$7F
        BEQ L_9083
        LDA X                       ; $18
        LSR A
        BCC L_9083
        LDA COLORMASK               ; $03
        EOR #$7F
        AND TEMPA                   ; $0A
        JMP CHRGENPLOT              ; $9087

L_9083:
        LDA COLORMASK               ; $03
        AND TEMPA                   ; $0A
CHRGENPLOT:
        PHA
        LDY WIDTH                   ; $1C
        LDA $90BE,Y
        LDY TEMP0F                  ; $0F
        BEQ L_9095
L_9091:
        ASL A
        DEY
        BNE L_9091
L_9095:
        STA $0E
        PLA
        AND $0E
        STA COLOR                   ; $11
        LDA X                       ; $18
        PHA
        ASL A
        ASL A
        STA X                       ; $18
        JSR ORPLOT2                 ; $9306
        PLA
        STA X                       ; $18
        LDA TEMP0F                  ; $0F
        PHA
        SEC
        ADC WIDTH                   ; $1C
        AND #$07
        STA TEMP0F                  ; $0F
        PLA
        SEC
        ADC WIDTH                   ; $1C
        AND #$F8
        BEQ L_90BD
        INC X                       ; $18
L_90BD:
        RTS

; =================================================================
; CHRGEN Font Data Reference (located at $9100)
; Font is embedded in the packed data below starting at byte offset +72
; 8 bytes per character, 7 visible bits per row (LSB = leftmost pixel)
;
; NOTE: Level 2 uses a DIFFERENT stylized font from levels 1 and 3!
;
; Visual patterns (# = pixel on, . = pixel off):
;
; SPACE (0)     A (1)         B (2)         C (3)         D (4)
; .......       .##....       #.###..       ..###..       #.##...
; .......       #..#...       .#...#.       .#...#.       ##..#..
; .......       ..#.#..       #....#.       #.#.#..       #....#.
; .......       .#...#.       #####..       #.#....       #....#.
; .......       .#####.       #....#.       #.#....       #....#.
; .......       .#...#.       .#...#.       .#...#.       ##..#..
; .......       #.....#       #.###..       ..###..       #.##...
; .......       .......       .......       .......       .......
;
; E (5)         F (6)         G (7)         H (8)         I (9)
; #.###..       #.###..       ..###..       ..###..       ......#
; .#...#.       .#...#.       .#...#.       .#...#.       .#####.
; #......       .#.....       #......       .#.....       #..#...
; ####...       ####...       #.####.       .####..       ...#...
; #......       .#.....       ##...#.       .#...#.       ...#..#
; .#...#.       .#.....       .#####.       .#...#.       .#####.
; #.###..       #......       .....#.       #....#.       #......
; .......       .......       ....##.       .......       .......
;
; Characters J-Z follow in stylized font design
; =================================================================

        .BYTE $01, $03, $07, $0F, $1F, $3F, $7F, $FF ; |#......##.....###....####...#####..######.##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $00, $00, $00, $00, $00, $00 ; |..............##############..............##############........................................................|
        .BYTE $00, $00, $06, $09, $14, $22, $3E, $22, $41, $00, $1D, $22, $21, $1F, $21, $22 ; |...............##....#..#.....#.#...#...#..#####..#...#.#.....#.......#.###...#...#.#....#.#####..#....#..#...#.|
        .BYTE $1D, $00, $1C, $22, $15, $05, $05, $22, $1C, $00, $0D, $13, $21, $21, $21, $13 ; |#.###...........###...#...#.#.#.#..#.#....#.#.....#...#...###.........#.##...##..#..#....#.#....#.#....#.##..#..|
        .BYTE $0D, $00, $1D, $22, $01, $0F, $01, $22, $1D, $00, $1D, $22, $02, $0F, $02, $02 ; |#.##..........#.###...#...#.#......####...#.......#...#.#.###.........#.###...#...#..#.....####....#......#.....|
        .BYTE $01, $00, $1C, $22, $01, $3D, $23, $3E, $20, $30, $1C, $22, $02, $1E, $22, $22 ; |#...............###...#...#.#......#.####.##...#..#####......#.....##...###...#...#..#......####...#...#..#...#.|
        .BYTE $21, $00, $40, $3E, $09, $08, $48, $3E, $01, $00, $40, $20, $20, $20, $22, $11 ; |#....#..............#.#####.#..#......#......#..#.#####.#...................#.....#......#......#..#...#.#...#..|
        .BYTE $0E, $00, $21, $12, $0A, $07, $0A, $12, $21, $00, $0C, $12, $02, $02, $02, $42 ; |.###..........#....#..#..#...#.#...###.....#.#....#..#..#....#..........##....#..#...#......#......#......#....#|
