; ----------------------------------------------------------------
; Sprite engine: XOR draw with collision detection
; 5 entry points:
;   DRAW2    ($9300) - XOR sprite blit (collision detecting)
;   CLRSCRN2 ($9303) - Clear hi-res screen
;   ORPLOT2  ($9306) - OR pixel onto screen
;   PLOT2    ($9309) - Direct pixel write
;   STABW2   ($930C) - Direct sprite write (overwrite mode)
;
; Uses HGRLO2/HGRHI2 tables at $9477/$9537
; Collision detected by AND-ing sprite with screen (REPORT $1F)
; ----------------------------------------------------------------

DRAW2:
        JMP DRAWIMPL2               ; $933D

CLRSCRN2:
        JMP CLRSCRIMPL2             ; $93C9

ORPLOT2:
        JMP ORPLOTIMPL2             ; $9325

PLOT2:
        JMP PLOTIMPL2               ; $930F

STABW2:
        JMP ERABW2                  ; $93FD

; ----------------------------------------------------------------
; PLOTIMPL2 - Direct pixel write to HGR page 2
; Overwrites screen byte with COLOR value
; ----------------------------------------------------------------
PLOTIMPL2:
        LDY Y                       ; get Y coordinate
        LDX HGR2LO,Y                ; get row address low byte
        LDA HGR2HI,Y                ; get row address high byte
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4 (7 pixels per byte)
        LSR A                       ; X/4 = byte offset
        TAY                         ; use as index
        LDA COLOR                   ; get pixel pattern
        STA (TOLO),Y                ; write to screen
        RTS

; ----------------------------------------------------------------
; ORPLOTIMPL2 - OR pixel onto HGR page 2 (additive)
; Preserves existing pixels, only adds new ones
; ----------------------------------------------------------------
ORPLOTIMPL2:
        LDY Y                       ; get Y coordinate
        LDX HGR2LO,Y                ; get row address low byte
        LDA HGR2HI,Y                ; get row address high byte
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; X/4 = byte offset
        TAY                         ; use as index
        LDA COLOR                   ; get pixel pattern
        ORA (TOLO),Y                ; OR with existing screen
        STA (TOLO),Y                ; write result
        RTS

; ----------------------------------------------------------------
; DRAWIMPL2 - XOR sprite draw with collision detection
; Main sprite engine - draws sprite using XOR for toggle effect
; Detects collisions by ANDing sprite data with screen content
; Result stored in REPORT ($1F): nonzero = collision
;
; Sub-pixel alignment: X mod 4 selects one of 4 pre-shifted
; sprite versions stored at consecutive pages (SHAPE+0..+3)
; ----------------------------------------------------------------
DRAWIMPL2:
        LDA #$00                    ; clear collision report
        STA REPORT                  ;
        ; --- Calculate sub-pixel offset and page ---
        LDA X                       ; get X coordinate
        LDY #$00                    ; counter for X/4
L_9345:
        INY                         ; count iterations
        SEC                         ;
        SBC #$04                    ; subtract 4
        BCC L_9351                  ; underflow -> done
        INY                         ; count again
        SEC                         ;
        SBC #$04                    ; subtract 4 again
        BCS L_9345                  ; continue if >= 0
L_9351:
        DEY                         ; adjust counter
        TYA                         ; get X/8 count
        AND #$01                    ; mod 2 for page offset
        CLC                         ;
        ROR A                       ; shift to high bits
        ROR A                       ; for memory alignment
        AND $20                     ; mask with collision flag
        STA SHPLO                   ; sprite data pointer low
        ; --- Select pre-shifted sprite version ---
        LDA X                       ; get X coordinate
        AND #$03                    ; X mod 4 = sub-pixel offset
        CLC                         ;
        ADC SHAPE                   ; add to base shape number
        STA SHAPE                   ; select shifted version (SHAPE+0..+3)
        ; --- Convert X to byte offset ---
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; X/4 = screen byte offset
        STA X                       ; store byte position
        STA XX                      ; save for row rendering
        LDA Y                       ; save Y coordinate
        STA YY                      ;
        ; --- Set sprite data address = (SHAPE | $40) * 256 ---
        LDA SHAPE                   ; get shape number
        ORA #$40                    ; add base page ($40 for level1/2)
        STA SHPHI                   ; sprite page = SHAPE | $40
        ; --- Read sprite dimensions from header ---
        LDY #$00                    ;
        LDA (SHPLO),Y               ; byte 0 = width (in bytes)
        STA WIDTH                   ;
        INY                         ;
        LDA (SHPLO),Y               ; byte 1 = height (in rows)
        STA HEIGHT                  ;
        INY                         ;
        TYA                         ; skip header (2 bytes)
        CLC                         ;
        ADC SHPLO                   ; point to pixel data
        STA SHPLO                   ;
; --- Main sprite row loop ---
L_9389:
        LDA WIDTH                   ; reset width counter
        STA TEMPWID                 ; for this row
        LDY YY                      ; get current Y row
        LDA HGR2LO,Y                ; get HGR row address low
        CLC                         ;
        ADC X                       ; add byte offset
        STA TOLO                    ; screen pointer low
        LDA HGR2HI,Y                ; get HGR row address high
        STA TOHI                    ; screen pointer high
        LDY #$00                    ; byte index within row
; --- Collision detection and XOR draw loop ---
L_939E:
        LDA (SHPLO),Y               ; get sprite byte
        AND COLOR                   ; mask with color
        CMP (TOLO),Y                ; compare to screen byte
        BEQ L_93AE                  ; equal -> no collision this byte
        ; --- Collision detected! ---
        LDA (TOLO),Y                ; get screen byte
        AND (SHPLO),Y               ; AND with sprite byte
        ORA REPORT                  ; accumulate in collision report
        STA REPORT                  ; nonzero means overlap
L_93AE:
        ; --- XOR draw sprite byte ---
        LDA (SHPLO),Y               ; get sprite byte
        AND COLOR                   ; apply color mask
        EOR (TOLO),Y                ; XOR with screen (toggle on/off)
        STA (TOLO),Y                ; write back to screen
        INY                         ; next byte in row
        DEC TEMPWID                 ; decrement width counter
        BNE L_939E                  ; more bytes -> continue row
        ; --- Move to next sprite row ---
        LDA SHPLO                   ; advance sprite pointer
        CLC                         ;
        ADC WIDTH                   ; by WIDTH bytes
        STA SHPLO                   ;
        INC YY                      ; next screen row
        DEC HEIGHT                  ; decrement row counter
        BNE L_9389                  ; more rows -> continue
        RTS                         ; sprite drawn

; ----------------------------------------------------------------
; CLRSCRIMPL2 - Clear hi-res screen to black
; Fills entire screen ($2000-$3FFF or $4000-$5FFF) with $00
; Then enables hi-res graphics mode
; ----------------------------------------------------------------
CLRSCRIMPL2:
        LDA #$00                    ; black color
        STA COLOR                   ;
        LDA #$BF                    ; start at Y = 191 (bottom)
        STA Y                       ;
L_93D1:
        LDA #$27                    ; X = 39 bytes per row (280/7)
        STA X                       ;
        LDA X                       ;
L_93D7:
        PHA                         ; save byte position
        ASL A                       ; multiply by 4
        ASL A                       ; for pixel coordinate
        STA X                       ;
        JSR PLOTIMPL2               ; write black byte
        PLA                         ; restore byte position
        STA X                       ;
        DEC X                       ; next byte (right to left)
        LDA X                       ;
        BPL L_93D7                  ; continue row
        DEC Y                       ; next row (bottom to top)
        LDA Y                       ;
        CMP #$FF                    ; done all rows?
        BNE L_93D1                  ; no -> continue
        ; --- Enable hi-res graphics mode ---
        STA TXTCLR                  ; clear text mode
        STA MIXCLR                  ; full screen (no text window)
        STA HIRES                   ; enable hi-res
        STA LOWSCR                  ; display page 1
        RTS

; ----------------------------------------------------------------
; ERABW2 - Direct sprite write (overwrite mode, no XOR)
; Same address calculation as DRAWIMPL2 but writes directly
; Used for redrawing sprites without toggle effect
; ----------------------------------------------------------------
ERABW2:
        LDA #$00
        STA REPORT                  ; $1F
        LDA X                       ; $18
        LDY #$00
L_9405:
        INY
        SEC
        SBC #$04
        BCC L_9411
        INY
        SEC
        SBC #$04
        BCS L_9405
L_9411:
        DEY
        TYA
        AND #$01
        CLC
        ROR A
        ROR A
        AND $20
        STA SHPLO                   ; $14
        LDA X                       ; $18
        AND #$03
        CLC
        ADC SHAPE                   ; $10
        STA SHAPE                   ; $10
        LDA X                       ; $18
        LSR A
        LSR A
        STA X                       ; $18
        STA XX                      ; $1A
        LDA Y                       ; $19
        STA YY                      ; $1B
        LDA SHAPE                   ; $10
        ORA #$40
        STA SHPHI                   ; $15
        LDY #$00
        LDA (SHPLO),Y               ; $14
        STA WIDTH                   ; $1C
        INY
        LDA (SHPLO),Y               ; $14
        STA HEIGHT                  ; $1D
        INY
        TYA
        CLC
        ADC SHPLO                   ; $14
        STA SHPLO                   ; $14
L_9449:
        LDA WIDTH                   ; $1C
        STA TEMPWID                 ; $1E
        LDY YY                      ; $1B
        LDA HGR2LO,Y                ; $9477
        CLC
        ADC X                       ; $18
        STA TOLO                    ; $16
        LDA HGR2HI,Y                ; $9537
        STA TOHI                    ; $17
        LDY #$00
L_945E:
        LDA (SHPLO),Y               ; $14
        AND COLOR                   ; $11
        STA (TOLO),Y                ; $16
        INY
        DEC TEMPWID                 ; $1E
        BNE L_945E
        LDA SHPLO                   ; $14
        CLC
        ADC WIDTH                   ; $1C
        STA SHPLO                   ; $14
        INC YY                      ; $1B
        DEC HEIGHT                  ; $1D
        BNE L_9449
        RTS

